```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

// Shared resource: s (semaphore) — a counting permit pool (R2).
struct Semaphore {
    permits: Mutex<usize>,
    available: Condvar,
}

impl Semaphore {
    fn new(initial: usize) -> Self {
        Semaphore {
            permits: Mutex::new(initial),
            available: Condvar::new(),
        }
    }

    // Acquire one permit. While waiting, the mutex is released, so the
    // worker currently holding a permit remains able to release it (R5).
    fn acquire(&self) {
        let mut permits = self.permits.lock().unwrap();
        while *permits == 0 {
            permits = self.available.wait(permits).unwrap();
        }
        *permits -= 1;
    }

    // Release one permit and wake a waiting worker so it can proceed (R5, R6).
    fn release(&self) {
        let mut permits = self.permits.lock().unwrap();
        *permits += 1;
        drop(permits);
        self.available.notify_one();
    }

    fn permits(&self) -> usize {
        *self.permits.lock().unwrap()
    }
}

// Common worker body: acquire, hold the permit while working (R3),
// then release. There is no early return or panic between acquire and
// release, so every path releases exactly as many times as it acquired (R4).
fn worker_body(s: &Semaphore, rounds: u32) {
    for _ in 0..rounds {
        s.acquire();
        // Critical section: only one worker can be here at a time (R3).
        for _ in 0..4 {
            std::hint::spin_loop();
            std::thread::yield_now();
        }
        s.release();
    }
}

// Role: w1 — acquires the permit twice, releasing after each use (R4).
fn w1(s: Arc<Semaphore>) {
    worker_body(&s, 2);
}

// Role: w2 — acquires the permit twice, releasing after each use (R4).
fn w2(s: Arc<Semaphore>) {
    worker_body(&s, 2);
}

fn main() {
    // One counting permit pool starting with exactly one permit (R2).
    let s = Arc::new(Semaphore::new(1));

    let s_for_w1 = Arc::clone(&s);
    let s_for_w2 = Arc::clone(&s);

    // Supervising task launches both workers (R1).
    let h1 = thread::spawn(move || w1(s_for_w1));
    let h2 = thread::spawn(move || w2(s_for_w2));

    // Supervisor waits for both workers to finish (R1, R6).
    h1.join().unwrap();
    h2.join().unwrap();

    // All permits returned: the pool is back to its initial count of 1.
    // Print exactly the required line and exit (R7).
    println!("DONE done={}", s.permits());
}
```

Notes on how the design satisfies the requirements:

- **R1**: `main` acts as the supervisor; it spawns `w1` and `w2` and joins both handles before printing.
- **R2**: `s` is a single `Arc<Semaphore>` initialized with exactly one permit, shared by both workers.
- **R3**: Each worker calls `acquire()` before its work section and `release()` after, so the two workers can never hold the permit (work) simultaneously.
- **R4**: Each worker runs two acquire/release rounds with no early returns, panics, or breaks between acquire and release, so releases always equal acquires on every path.
- **R5**: The semaphore is built on `Mutex` + `Condvar`; `Condvar::wait` atomically releases the mutex while waiting, so a worker holding a permit is never blocked from calling `release()` by a waiting worker.
- **R6**: The semaphore is fair enough in practice (each release notifies a waiter), work sections are finite, and each worker performs a bounded number of rounds — every interleaving terminates.
- **R7**: After both workers finish, the permit count is back to 1, and the program prints exactly `DONE done=1` and exits.
